css:
/* ใบแจ้งหนี้เงินมัดจำ — self-contained Sales Invoice print CSS */
@font-face {
    font-family: "TH Sarabun Document";
    src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
    font-style: normal;
    font-weight: 400 700;
    font-display: block;
}

@page {
    size: 210mm 297mm;
    margin: 0;
}

html,
body {
    margin: 0 !important;
    padding: 0 !important;
}

.print-format {
    width: 210mm !important;
    min-height: 297mm !important;
    margin: 0 !important;
    padding: 0 !important;
}

.cd-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.cd-table td,
.cd-table th {
    border-color: var(--cd-border, #202020);
}

.cd-table tr {
    break-inside: avoid;
    page-break-inside: avoid;
}

.cd-invoice.cd-invoice {
    --cd-font: "TH Sarabun Document", "TH SarabunPSK", "Noto Sans Thai", sans-serif;
    --cd-fs-base: 4.10mm;
    --cd-fs-value: 4.516mm;
    --cd-fs-label: 3.85mm;
    --cd-fs-money: 4.00mm;
    --cd-fs-total: 5.821mm;
    --cd-fs-doc-title: 6.10mm;
    --cd-fs-company: 7.00mm;
    --cd-fs-company-line: 4.60mm;
    --cd-fs-sum-label: 4.10mm;
    --cd-fs-terms: 3.40mm;
    --cd-lh-field: 6.20mm;
    --cd-lh-label: 3.35mm;
    --cd-lh-money: 5.20mm;
    --cd-lh-address: 5.15mm;
    --cd-lh-terms: 4.20mm;
    --cd-ink: #202020;
    --cd-muted: #5f6368;
    --cd-border: #171717;
    --cd-rule-w: 0.215mm;
    --cd-rule: var(--cd-rule-w) solid var(--cd-border);
    --cd-radius: 3.20mm;
    --cd-pill-radius: 6.00mm;
    --copy-color: #b3b3b3;
    --cd-pad-box-y: 2.00mm;
    --cd-pad-box-x: 3.20mm;
    --cd-gap-box: 1.20mm;
    --cd-label-w: 20.00mm;
    --cd-pad-label-r: 1.60mm;
    --cd-line-h: 6.15mm;
    --cd-item-lh: 5.20mm;
    --cd-fs-item: 4.10mm;
    --cd-trace-fs: 3.10mm;
    --cd-trace-lh: 4.00mm;
    --cd-trace-pull: 1.30mm;
    --cd-trace-gap: 0.30mm;
    --cd-trace-tail: 1.40mm;
    --cd-grid-w: 188.32mm;
    --cd-col-no: 11.07mm;
    --cd-col-desc: 107.93mm;
    --cd-col-qty: 23.11mm;
    --cd-col-price: 19.80mm;
    --cd-col-amount: 26.41mm;
    --cd-x-desc: var(--cd-col-no);
    --cd-x-qty: calc(var(--cd-col-no) + var(--cd-col-desc));
    --cd-x-price: calc(var(--cd-x-qty) + var(--cd-col-qty));
    --cd-x-amount: calc(var(--cd-x-price) + var(--cd-col-price));
    --cd-head-h: 6.93mm;
    --cd-table-h: 79.47mm;
    --cd-body-h: calc(var(--cd-table-h) - var(--cd-head-h));
    --cd-summary-h: 55.81mm;
    --cd-grand-h: 9.33mm;
    --cd-summary-top-h: calc(var(--cd-summary-h) - var(--cd-grand-h));
    --cd-grid-h: calc(var(--cd-table-h) + var(--cd-summary-h));
    --cd-sum-term: 60%;
    --cd-sum-side: 40%;
    --cd-sum-rows: 6;
    --cd-pad-sum-x: 2.60mm;
    --cd-pad-sum-y: 0.40mm;
    --cd-pad-terms: 2.00mm 3.00mm;
    --ab-pad-x: 2.30mm;
    --ab-pad-y: 2.20mm;
    --ab-head-h: 9.00mm;
    --ab-sig-w: 36.50mm;
    --ab-date-w: 15.50mm;
    --ab-line-h: 4.60mm;
    --ab-sig-img-w: 32.00mm;
    --ab-sig-img-h: 7.50mm;
    --ab-sig-drop: 0.50mm;
    --ab-rule: 0.159mm solid #565656;
    --ab-fs-head: 3.75mm;
    --ab-fs-body: 3.10mm;
    --ab-fs-micro: 2.80mm;
    box-sizing: border-box;
    position: relative;
    width: 210mm;
    min-width: 210mm;
    max-width: 210mm;
    height: 297mm;
    min-height: 297mm;
    max-height: 297mm;
    margin: 0;
    overflow: hidden;
    color: var(--cd-ink) !important;
    background: #fff;
    font-family: var(--cd-font) !important;
    font-size: var(--cd-fs-base) !important;
    font-weight: 400;
    line-height: 1;
    break-after: page;
    page-break-after: always;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.cd-invoice.cd-invoice * {
    box-sizing: border-box;
    font-family: inherit !important;
}

.cd-invoice.cd-invoice.last-page {
    break-after: auto;
    page-break-after: auto;
}

.cd-invoice.cd-invoice .cd-corporate-header {
    position: absolute;
    left: 0;
    top: 0;
    width: 210mm;
    height: 52.30mm;
}

.cd-invoice.cd-invoice .cd-corporate-header>div,
.cd-invoice.cd-invoice .cd-corporate-header>img {
    position: absolute;
    margin: 0;
    white-space: nowrap;
}

.cd-invoice.cd-invoice .company-logo {
    left: 12.70mm;
    top: 18.99mm;
    width: 20.39mm;
    height: 7.78mm;
    object-fit: contain;
}

.cd-invoice.cd-invoice .company-name {
    left: 35.88mm;
    top: 13.49mm;
    font-size: var(--cd-fs-company);
    line-height: 7.40mm;
}

.cd-invoice.cd-invoice .company-address {
    left: 35.88mm;
    top: 22.35mm;
    font-size: var(--cd-fs-company-line);
    line-height: 5.20mm;
}

.cd-invoice.cd-invoice .company-contact {
    left: 35.88mm;
    top: 28.76mm;
    font-size: var(--cd-fs-company-line);
    line-height: 5.20mm;
}

.cd-invoice.cd-invoice .company-tax-label,
.cd-invoice.cd-invoice .company-tax-value,
.cd-invoice.cd-invoice .company-branch {
    top: 36.21mm;
    font-size: var(--cd-fs-label);
    line-height: 4.40mm;
}

.cd-invoice.cd-invoice .company-tax-label {
    left: 35.95mm;
}

.cd-invoice.cd-invoice .company-tax-value {
    left: 78.45mm;
}

.cd-invoice.cd-invoice .company-branch {
    left: 104.73mm;
}

.cd-invoice.cd-invoice .document-title {
    left: 133.91mm;
    top: 34.81mm;
    width: 69.75mm;
    height: 11.60mm;
    padding: 1.18mm 1.20mm 0;
    overflow: hidden;
    border-radius: var(--cd-pill-radius);
    background: var(--copy-color);
    font-size: var(--cd-fs-doc-title);
    font-weight: 700;
    line-height: 8.80mm;
    text-align: center;
}

.cd-invoice.cd-invoice.document-abbreviated-receipt .document-title {
    font-size: 5.35mm;
}

.cd-invoice.cd-invoice.document-deposit-invoice .document-title {
    font-size: 5.55mm;
}

.cd-invoice.cd-invoice .copy-title {
    left: 141.00mm;
    top: 48.18mm;
    width: 53.40mm;
    font-size: var(--cd-fs-total);
    font-weight: 700;
    line-height: 7.58mm;
    text-align: center;
}

.cd-invoice.cd-invoice .th {
    display: block;
    font-size: var(--cd-fs-label);
    line-height: var(--cd-lh-label);
    white-space: nowrap;
}

.cd-invoice.cd-invoice .info-box {
    position: absolute;
    top: 55.78mm;
    height: 50.52mm;
    padding: var(--cd-pad-box-y) var(--cd-pad-box-x);
    display: flex;
    flex-direction: column;
    gap: var(--cd-gap-box);
    overflow: hidden;
    border: var(--cd-rule);
    border-radius: var(--cd-radius);
}

.cd-invoice.cd-invoice .customer-box {
    left: 14.40mm;
    width: 96.91mm;
    --cd-label-w: 15.00mm;
}

.cd-invoice.cd-invoice .invoice-box {
    left: 112.85mm;
    width: 90.34mm;
    --cd-label-w: 24.00mm;
}

.cd-invoice.cd-invoice .return-document-box {
    --cd-label-w: 31.50mm;
    gap: 0;
}

.cd-invoice.cd-invoice .deposit-document-box {
    --cd-label-w: 26.00mm;
    gap: 0;
}

.cd-invoice.cd-invoice .field-table {
    flex: 0 0 auto;
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.cd-invoice.cd-invoice .field-table td {
    height: var(--cd-lh-field);
    padding: 0 !important;
    border: 0;
    overflow: hidden;
    vertical-align: middle;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.cd-invoice.cd-invoice .field-label {
    width: var(--cd-label-w);
    padding-right: var(--cd-pad-label-r) !important;
    font-size: var(--cd-fs-label);
    font-weight: 700;
    text-align: left;
}

.cd-invoice.cd-invoice .field-value {
    font-size: var(--cd-fs-value);
    text-align: left;
}

.cd-invoice.cd-invoice .field-value.is-strong {
    font-weight: 700;
}

.cd-invoice.cd-invoice .field-spacer {
    flex: 1 1 auto;
    min-height: 0;
}

.cd-invoice.cd-invoice .credit-row {
    flex: 0 0 auto;
    height: var(--cd-lh-field);
    display: flex;
    align-items: center;
    min-width: 0;
    white-space: nowrap;
}

.cd-invoice.cd-invoice .credit-row>* {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

.cd-invoice.cd-invoice .credit-row>.field-label:first-child {
    flex: 0 0 var(--cd-label-w);
}

.cd-invoice.cd-invoice .credit-days {
    flex: 0 0 8.00mm;
    padding-right: 1.00mm;
    text-align: right;
}

.cd-invoice.cd-invoice .credit-unit {
    flex: 0 0 8.00mm;
    padding-right: 2.00mm;
}

.cd-invoice.cd-invoice .due-label-inline {
    flex: 0 0 16.00mm;
    width: auto;
    padding-right: 1.20mm !important;
}

.cd-invoice.cd-invoice .due-value {
    flex: 1 1 auto;
}

.cd-invoice.cd-invoice .customer-body {
    flex: 1 1 auto;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.cd-invoice.cd-invoice .customer-name {
    flex: 0 0 auto;
    overflow: hidden;
    font-size: var(--cd-fs-value);
    font-weight: 700;
    line-height: var(--cd-lh-field);
    white-space: nowrap;
    text-overflow: ellipsis;
}

.cd-invoice.cd-invoice .customer-address {
    flex: 1 1 auto;
    min-height: 0;
    overflow: hidden;
    font-size: var(--cd-fs-value);
    font-weight: 700;
    line-height: var(--cd-lh-address);
}

.cd-invoice.cd-invoice .customer-address br {
    display: block;
}

.cd-invoice.cd-invoice .invoice-grid {
    position: absolute;
    left: 14.63mm;
    top: 107.47mm;
    width: var(--cd-grid-w);
    height: var(--cd-grid-h);
    overflow: hidden;
    border: var(--cd-rule);
    border-radius: var(--cd-radius);
}

.cd-invoice.cd-invoice .grid-vline {
    position: absolute;
    top: 0;
    height: var(--cd-table-h);
    width: 0;
    border-left: var(--cd-rule);
    z-index: 3;
}

.cd-invoice.cd-invoice .line-no {
    left: var(--cd-x-desc);
}

.cd-invoice.cd-invoice .line-description {
    left: var(--cd-x-qty);
}

.cd-invoice.cd-invoice .line-quantity {
    left: var(--cd-x-price);
}

.cd-invoice.cd-invoice .line-unit-price {
    left: var(--cd-x-amount);
}

.cd-invoice.cd-invoice .product-head {
    position: absolute;
    left: 0;
    top: 0;
    width: var(--cd-grid-w);
    height: var(--cd-head-h);
    background: var(--copy-color);
    border-bottom: var(--cd-rule);
}

.cd-invoice.cd-invoice .head-cell {
    position: absolute;
    top: 0;
    height: var(--cd-head-h);
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
}

.cd-invoice.cd-invoice .product-head .col-no {
    left: 0;
    width: var(--cd-col-no);
}

.cd-invoice.cd-invoice .product-head .col-description {
    left: var(--cd-x-desc);
    width: var(--cd-col-desc);
}

.cd-invoice.cd-invoice .product-head .col-quantity {
    left: var(--cd-x-qty);
    width: var(--cd-col-qty);
}

.cd-invoice.cd-invoice .product-head .col-unit-price {
    left: var(--cd-x-price);
    width: var(--cd-col-price);
}

.cd-invoice.cd-invoice .product-head .col-amount {
    left: var(--cd-x-amount);
    width: var(--cd-col-amount);
}

.cd-invoice.cd-invoice .product-body {
    position: absolute;
    left: 0;
    top: var(--cd-head-h);
    width: var(--cd-grid-w);
    height: var(--cd-body-h);
    overflow: hidden;
    border-bottom: var(--cd-rule);
}

.cd-invoice.cd-invoice .item-lines {
    position: relative;
    z-index: 2;
    width: var(--cd-grid-w);
    border-collapse: collapse;
    table-layout: fixed;
    font-size: var(--cd-fs-item);
    line-height: var(--cd-item-lh);
}

.cd-invoice.cd-invoice .item-lines col.col-no {
    width: var(--cd-col-no);
}

.cd-invoice.cd-invoice .item-lines col.col-description {
    width: var(--cd-col-desc);
}

.cd-invoice.cd-invoice .item-lines col.col-quantity {
    width: var(--cd-col-qty);
}

.cd-invoice.cd-invoice .item-lines col.col-unit-price {
    width: var(--cd-col-price);
}

.cd-invoice.cd-invoice .item-lines col.col-amount {
    width: var(--cd-col-amount);
}

.cd-invoice.cd-invoice .item-lines td {
    height: auto;
    padding: 0 !important;
    overflow: hidden;
    border: 0;
    font-size: var(--cd-fs-item);
    line-height: var(--cd-item-lh);
    white-space: nowrap;
    text-overflow: clip;
    vertical-align: top;
}

.cd-invoice.cd-invoice .item-row {
    break-inside: avoid;
    page-break-inside: avoid;
}

.cd-invoice.cd-invoice .item-main-line {
    min-height: var(--cd-line-h);
    overflow: hidden;
    font-size: var(--cd-fs-item);
    line-height: var(--cd-item-lh);
    white-space: nowrap;
    text-overflow: clip;
}

.cd-invoice.cd-invoice .cell-description {
    white-space: normal;
}

.cd-invoice.cd-invoice .cell-description .item-main-line {
    height: auto;
    overflow: visible;
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.cd-invoice.cd-invoice .traceability-line {
    min-height: 0;
    height: auto;
    margin-top: var(--cd-trace-gap);
    overflow: visible;
    font-size: var(--cd-trace-fs);
    line-height: var(--cd-trace-lh);
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.cd-invoice.cd-invoice .item-main-line+.traceability-line {
    margin-top: calc(-1 * var(--cd-trace-pull));
}

.cd-invoice.cd-invoice .cell-description .traceability-line:last-child {
    margin-bottom: var(--cd-trace-tail);
}

.cd-invoice.cd-invoice .traceability-label {
    font-weight: 700;
}

.cd-invoice.cd-invoice .item-lines .cell-no {
    padding-right: 2.60mm !important;
    text-align: right;
}

.cd-invoice.cd-invoice .item-lines .cell-description {
    padding-left: 1.75mm !important;
    padding-right: 1.20mm !important;
    text-align: left;
}

.cd-invoice.cd-invoice .item-lines .cell-quantity {
    padding-right: 1.65mm !important;
    text-align: right;
}

.cd-invoice.cd-invoice .item-lines .cell-money {
    padding-right: 1.05mm !important;
    text-align: right;
}

.cd-invoice.cd-invoice .summary-area {
    position: absolute;
    left: 0;
    top: var(--cd-table-h);
    width: var(--cd-grid-w);
    height: var(--cd-summary-h);
    display: flex;
    flex-direction: column;
}

.cd-invoice.cd-invoice .summary-top {
    flex: 0 0 var(--cd-summary-top-h);
    min-height: 0;
    display: flex;
    border-bottom: var(--cd-rule);
}

.cd-invoice.cd-invoice .summary-term {
    flex: 0 0 var(--cd-sum-term);
    min-width: 0;
    padding: var(--cd-pad-terms);
    overflow: hidden;
    border-right: var(--cd-rule);
}

.cd-invoice.cd-invoice .terms-text {
    height: 100%;
    overflow: hidden;
    font-size: var(--cd-fs-terms);
    line-height: var(--cd-lh-terms);
}

.cd-invoice.cd-invoice .terms-text p {
    margin: 0 0 1mm;
}

.cd-invoice.cd-invoice .terms-text ul,
.cd-invoice.cd-invoice .terms-text ol {
    margin: 0 0 1mm;
    padding-left: 5mm;
}

.cd-invoice.cd-invoice .receipt-note {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    padding-bottom: 0.70mm;
    font-size: 2.93mm;
}

.cd-invoice.cd-invoice .reason-box {
    display: block;
}

.cd-invoice.cd-invoice .reason-title {
    font-weight: 700;
    font-size: 3.85mm;
    line-height: 4.50mm;
}

.cd-invoice.cd-invoice .reason-value {
    margin-top: 1mm;
    font-size: 4.00mm;
    line-height: 4.60mm;
    white-space: normal;
    overflow-wrap: anywhere;
}

.cd-invoice.cd-invoice .deposit-heading {
    margin-bottom: 1mm;
    font-weight: 700;
    font-size: 3.85mm;
}

.cd-invoice.cd-invoice .summary-side {
    flex: 0 0 var(--cd-sum-side);
    min-width: 0;
    display: flex;
}

.cd-invoice.cd-invoice .summary-table {
    width: 100%;
    height: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.cd-invoice.cd-invoice .summary-table tr {
    height: calc(100% / var(--cd-sum-rows));
}

.cd-invoice.cd-invoice .summary-table td {
    padding: var(--cd-pad-sum-y) var(--cd-pad-sum-x) !important;
    border: 0;
    overflow: hidden;
    vertical-align: middle;
    white-space: nowrap;
    text-overflow: clip;
}

.cd-invoice.cd-invoice .sum-label {
    width: 60%;
    border-right: var(--cd-rule) !important;
    font-size: var(--cd-fs-sum-label);
    font-weight: 700;
    text-align: left;
}

.cd-invoice.cd-invoice.document-credit-note .sum-label,
.cd-invoice.cd-invoice.document-debit-note .sum-label {
    font-size: 3.55mm;
    padding-left: 1.50mm !important;
    padding-right: 1.20mm !important;
}

.cd-invoice.cd-invoice .sum-value {
    width: 40%;
    font-size: var(--cd-fs-money);
    text-align: right;
}

.cd-invoice.cd-invoice .summary-bottom {
    flex: 0 0 var(--cd-grand-h);
    min-height: 0;
    display: flex;
    align-items: stretch;
    background: var(--copy-color);
}

.cd-invoice.cd-invoice .summary-bottom>div {
    display: flex;
    align-items: center;
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
}

.cd-invoice.cd-invoice .amount-in-words {
    flex: 0 0 var(--cd-sum-term);
    justify-content: center;
    padding: 0 var(--cd-pad-sum-x);
    border-right: var(--cd-rule);
    font-size: var(--cd-fs-money);
}

.cd-invoice.cd-invoice .grand-total-label {
    flex: 0 0 24%;
    padding: 0 var(--cd-pad-sum-x);
    border-right: var(--cd-rule);
    font-size: var(--cd-fs-sum-label);
    font-weight: 700;
}

.cd-invoice.cd-invoice.document-credit-note .grand-total-label,
.cd-invoice.cd-invoice.document-debit-note .grand-total-label,
.cd-invoice.cd-invoice.document-deposit-invoice .grand-total-label {
    font-size: 3.45mm;
}

.cd-invoice.cd-invoice .grand-total-value {
    flex: 0 0 16%;
    justify-content: flex-end;
    padding: 0 var(--cd-pad-sum-x);
    font-size: var(--cd-fs-total);
}

.cd-invoice.cd-invoice .approval-box {
    position: absolute;
    left: 14.40mm;
    top: 244.10mm;
    width: 188.56mm;
    height: 43.66mm;
    display: flex;
    overflow: hidden;
    border: var(--cd-rule);
    border-radius: var(--cd-radius);
    font-size: var(--ab-fs-body);
    line-height: 1.25;
}

.cd-invoice.cd-invoice .approval-left,
.cd-invoice.cd-invoice .approval-right {
    flex: 0 0 31.75%;
    min-width: 0;
    padding: var(--ab-pad-y) var(--ab-pad-x);
    display: flex;
    flex-direction: column;
}

.cd-invoice.cd-invoice .approval-left {
    border-right: var(--cd-rule);
}

.cd-invoice.cd-invoice .approval-column {
    flex: 1 1 auto;
    min-width: 0;
    padding: 2.10mm 2.20mm 1.30mm;
    overflow: hidden;
    border-right: var(--cd-rule);
    font-size: 3.45mm;
    line-height: 4.15mm;
}

.cd-invoice.cd-invoice .notes-list {
    margin: 0;
    padding: 0 0 0 4.20mm;
}

.cd-invoice.cd-invoice .notes-list li {
    margin: 0 0 0.35mm;
    padding: 0;
}

.cd-invoice.cd-invoice .two-column-approval .approval-notes {
    flex: 0 0 50%;
    min-width: 0;
    padding: 2.20mm 3.00mm;
    border-right: var(--cd-rule);
    overflow: hidden;
}

.cd-invoice.cd-invoice .two-column-approval .wide-signatures {
    flex: 0 0 50%;
}

.cd-invoice.cd-invoice .notes-heading {
    margin-bottom: 1.30mm;
    font-size: 3.75mm;
    font-weight: 700;
}

.cd-invoice.cd-invoice .notes-content {
    height: 33mm;
    overflow: hidden;
    font-size: 3.35mm;
    line-height: 4.10mm;
}

.cd-invoice.cd-invoice .payment-reference {
    margin-top: 1.20mm;
}

.cd-invoice.cd-invoice .footer-reason-title {
    margin-bottom: .6mm;
}

.cd-invoice.cd-invoice .three-column-approval .approval-third {
    flex: 0 0 33.333%;
    min-width: 0;
    padding: var(--ab-pad-y) var(--ab-pad-x);
    display: flex;
    flex-direction: column;
}

.cd-invoice.cd-invoice .three-column-approval .middle-third {
    border-left: var(--cd-rule);
    border-right: var(--cd-rule);
}

.cd-invoice.cd-invoice .three-column-approval {
    --ab-sig-w: 35mm;
    --ab-date-w: 15mm;
    --ab-sig-img-w: 28mm;
    --ab-fs-body: 2.85mm;
}

.cd-invoice.cd-invoice .compact-head {
    flex-basis: 8mm;
}

.cd-invoice.cd-invoice .approval-head {
    flex: 0 0 var(--ab-head-h);
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.cd-invoice.cd-invoice .received-heading,
.cd-invoice.cd-invoice .signature-company {
    font-size: var(--ab-fs-head);
    font-weight: 700;
    text-align: center;
    white-space: nowrap;
}

.cd-invoice.cd-invoice .brand-top {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    font-size: var(--ab-fs-micro);
}

.cd-invoice.cd-invoice .signature-row {
    flex: 1 1 0;
    min-height: 0;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    gap: 0.70mm;
}

.cd-invoice.cd-invoice .signature-lines,
.cd-invoice.cd-invoice .signature-labels {
    display: flex;
    align-items: flex-end;
}

.cd-invoice.cd-invoice .signature-line,
.cd-invoice.cd-invoice .date-line {
    height: var(--ab-line-h);
    padding-bottom: 0.30mm;
    border-bottom: var(--ab-rule);
    display: flex;
    align-items: flex-end;
    justify-content: center;
    white-space: nowrap;
}

.cd-invoice.cd-invoice .signature-line {
    flex: 0 1 var(--ab-sig-w);
    position: relative;
    z-index: 2;
    overflow: visible;
}

.cd-invoice.cd-invoice .date-line {
    flex: 0 0 var(--ab-date-w);
    margin-left: auto;
    overflow: hidden;
}

.cd-invoice.cd-invoice .action-signature-image {
    display: block;
    position: relative;
    z-index: 3;
    width: var(--ab-sig-img-w);
    max-width: 100%;
    height: var(--ab-sig-img-h);
    max-height: none;
    margin: 0 0 calc(-1 * var(--ab-sig-drop));
    border: 0;
    object-fit: contain;
}

.cd-invoice.cd-invoice .signature-caption {
    flex: 0 1 var(--ab-sig-w);
    min-width: 0;
    display: flex;
    align-items: baseline;
    justify-content: center;
    gap: 0.60mm;
}

.cd-invoice.cd-invoice .date-caption {
    flex: 0 0 var(--ab-date-w);
    margin-left: auto;
    text-align: center;
}

.cd-invoice.cd-invoice .action-name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.cd-invoice.cd-invoice .signature-role {
    flex: 0 0 auto;
    white-space: nowrap;
}

.cd-invoice.copy-original {
    --copy-color: #b3b3b3;
}

.cd-invoice.copy-customer {
    --copy-color: #8ff5b1;
}

.cd-invoice.copy-accounting {
    --copy-color: #ff9829;
}

.cd-invoice.copy-sales {
    --copy-color: #ffffa0;
}

/* Signature-only footer: notes live in the single summary-term area. */
.cd-invoice.cd-invoice .signature-only-footer {
    display: flex;
    align-items: stretch;
    padding: 0;
}

.cd-invoice.cd-invoice .signature-only-footer .signature-pane {
    flex: 1 1 0;
    min-width: 0;
    padding: var(--ab-pad-y) var(--ab-pad-x);
    display: flex;
    flex-direction: column;
}

.cd-invoice.cd-invoice .signature-only-footer .signature-pane + .signature-pane {
    border-left: var(--cd-rule);
}

.cd-invoice.cd-invoice .signature-only-footer .signature-row {
    flex: 1 1 0;
}

.cd-invoice.cd-invoice .signature-only-footer .approval-head {
    flex: 0 0 var(--ab-head-h);
}

.cd-invoice.cd-invoice .signature-only-footer.compact-signatures .signature-pane {
    justify-content: flex-end;
}

.cd-invoice.cd-invoice .signature-only-footer.delivery-signatures .signature-pane,
.cd-invoice.cd-invoice .signature-only-footer.three-signatures .signature-pane {
    flex: 0 0 50%;
}

.cd-invoice.cd-invoice .signature-only-footer.three-signatures .signature-pane {
    flex-basis: 33.333%;
}

.cd-invoice.cd-invoice .signature-only-footer .received-heading,
.cd-invoice.cd-invoice .signature-only-footer .signature-company {
    white-space: normal;
    line-height: 4.15mm;
}

.cd-invoice.cd-invoice .terms-text.receipt-note {
    display: block;
    text-align: left;
    padding-bottom: 0;
}

.cd-invoice.cd-invoice .terms-heading {
    margin-bottom: 1.10mm;
    font-size: 3.85mm;
    font-weight: 700;
    line-height: 4.50mm;
}

.cd-invoice.cd-invoice .terms-text .notes-list {
    margin-top: 1.00mm;
}

html:
{#
ERPNext Custom Print Format: Sales Invoice
Connect Diagnostics — unified Sales Invoice print structure.
#}

{% macro corporate_header(
company_name,
company_address,
company_contact,
tax_label,
tax_id,
branch,
document_title,
copy_title,
logo_src="/assets/connect_diagnostics_core/images/cd_logo_v2.jpg",
logo_alt="Connect Diagnostics"
) -%}
<header class="document-header cd-corporate-header">
    <img class="company-logo" src="{{ logo_src }}" alt="{{ logo_alt }}">
    <div class="company-name">{{ company_name }}</div>
    <div class="company-address">{{ company_address }}</div>
    <div class="company-contact">{{ company_contact }}</div>
    <div class="company-tax-label">{{ tax_label }}</div>
    <div class="company-tax-value">{{ tax_id }}</div>
    <div class="company-branch">{{ branch }}</div>
    <div class="document-title">{{ document_title }}</div>
    <div class="copy-title">{{ copy_title }}</div>
</header>
{%- endmacro %}

{% macro item_table(columns=(), classes="") -%}
<table class="cd-table{% if classes %} {{ classes }}{% endif %}">
    {% if columns %}
    <colgroup>
        {% for class_name in columns %}
        <col{% if class_name %} class="{{ class_name }}"{% endif %}>
        {% endfor %}
    </colgroup>
    {% endif %}
    {{ caller() }}
</table>
{%- endmacro %}

{% macro field_row(label, value, strong=False) -%}
<tr>
    <td class="field-label">{{ label }}</td>
    <td class="field-value{% if strong %} is-strong{% endif %}">{{ value }}</td>
</tr>
{%- endmacro %}

{% macro summary_row(label, value) -%}
<tr>
    <td class="sum-label">{{ label }}</td>
    <td class="sum-value">{{ format_money(value) }}</td>
</tr>
{%- endmacro %}

{% macro signature_row(action, role) -%}
<div class="signature-row">
    <div class="signature-lines">
        <span class="signature-line">
            {%- if action.get("signature") %}<img class="action-signature-image"
                src="{{ action.get("signature") | e }}" alt="">{% endif -%}
        </span>
        <span class="date-line">
            {%- if action.get("acted_at") %}{{ format_date(action.get("acted_at")) }}{% endif -%}
        </span>
    </div>
    <div class="signature-labels">
        <span class="signature-caption">
            <span class="action-name">{{ action.get("name", "") }}</span>
            <span class="signature-role">({{ role }})</span>
        </span>
        <span class="date-caption">วันที่</span>
    </div>
</div>
{%- endmacro %}

{% set print_data = get_sales_invoice_print_context(doc) %}
{% set print_context = print_data.print_context %}
{% set print_actions = get_print_action_context(doc) %}
{% set received_action = print_actions.get("received", {}) %}
{% set delivered_action = print_actions.get("delivered", {}) %}
{% set authorized_action = print_actions.get("authorized", {}) %}
{% set checked_action = print_actions.get("checked", {}) %}
{% set return_received_action = print_actions.get("return_received", {}) %}
{% set warehouse_checked_action = print_actions.get("warehouse_checked", {}) %}
{% set item_pages = print_data.item_pages %}
{% set item_page_count = print_data.item_page_count %}
{% set first_item = doc.items[0] if doc.items else none %}
{% set credit_days = (doc.payment_schedule[0].get("credit_days") or 0) if doc.payment_schedule else 0 %}
{% set sales_order_no = first_item.sales_order if first_item and first_item.sales_order else (doc.get("sales_order_no") or "") %}
{% set salesman = doc.sales_team[0].sales_person if doc.sales_team else (doc.get("salesman") or "") %}
{% set deposit = doc.get("advance_paid") or doc.get("deposit_amount") or 0 %}
{% set gross_amount = doc.get("total") or 0 %}
{% set discount_amount = doc.get("discount_amount") or 0 %}
{% set after_discount = gross_amount - discount_amount %}
{% set after_deposit = after_discount - deposit %}
{% set vat_rate = ((doc.taxes[0].rate if doc.taxes else 0) or 0) %}
{% set vat_amount = doc.get("total_taxes_and_charges") or 0 %}
{% set total_print_pages = item_page_count %}


{% set deposit_percent = doc.get("deposit_percentage") or doc.get("custom_deposit_percentage") or 0 %}
{% set deposit_net = doc.get("net_total") or after_discount %}
{% set deposit_total = doc.get("grand_total") or 0 %}

{% set DOCUMENT_TITLE = "ใบแจ้งหนี้เงินมัดจำ" %}
{% set summary_row_count = 4 %}

{% for copy in print_context.copies %}
{% set copy_loop = loop %}
{% for page_items in item_pages %}
{% set page_loop = loop %}
{% set current_print_page = page_loop.index %}

<div class="cd-invoice cd-a4-page document-deposit-invoice copy-{{ copy.kind }}{% if copy_loop.last and page_loop.last %} last-page{% endif %}"
    style="--cd-sum-rows: {{ summary_row_count }};">

{{ corporate_header(
    company_name="บริษัท คอนเนคไดแอกโนสติกส์ จำกัด",
    company_address="1/57-58 เวนิส ดี ไอริส ซอยวัชรพล 2/7 แขวงท่าแร้ง เขตบางเขน กรุงเทพฯ 10220",
    company_contact="02-3470109&nbsp;&nbsp;&nbsp; www.connectdiagnostics.com",
    tax_label="เลขประจำตัวผู้เสียภาษี/ Tax ID",
    tax_id="0105551058581",
    branch="สำนักงานใหญ่",
    document_title=DOCUMENT_TITLE,
    copy_title=copy.label
) }}


<section class="info-box customer-box">
    <table class="field-table">
        <tbody>
            {{ field_row("ลูกค้า", doc.customer or "") }}
        </tbody>
    </table>

    <div class="customer-body">
        <div class="customer-name">{{ print_context.customer_name }}</div>
        <div class="customer-address">{{ (doc.address_display or "") | safe }}</div>
    </div>

    <table class="field-table">
        <tbody>
            {{ field_row("อ้างอิง", doc.po_no or doc.get("po_number") or "", strong=True) }}
        </tbody>
    </table>
</section>


<section class="info-box invoice-box deposit-document-box">
    <table class="field-table">
        <tbody>
            {{ field_row("เลขที่", doc.name, strong=True) }}
            {{ field_row("วันที่", format_date(doc.posting_date) if print_context.show_date else "") }}
            {{ field_row("เลขที่ใบสั่งขาย", sales_order_no, strong=True) }}
        </tbody>
    </table>

    <div class="field-spacer"></div>

    <table class="field-table">
        <tbody>
            {{ field_row("อัตราเงินมัดจำ", (format_money(deposit_percent) ~ " %") if deposit_percent else "") }}
            {{ field_row("ครบกำหนด", format_date(doc.due_date)) }}
            {{ field_row("พนักงานขาย", salesman) }}
        </tbody>
    </table>
</section>


<section class="invoice-grid">
    <span class="grid-vline line-no"></span>
    <span class="grid-vline line-description"></span>
    <span class="grid-vline line-quantity"></span>
    <span class="grid-vline line-unit-price"></span>

    <div class="product-head">
        <div class="head-cell col-no"><span class="th">ลำดับ</span></div>
        <div class="head-cell col-description"><span class="th">รหัสสินค้า/รายละเอียด</span></div>
        <div class="head-cell col-quantity"><span class="th">จำนวน</span></div>
        <div class="head-cell col-unit-price"><span class="th">หน่วยละ</span></div>
        <div class="head-cell col-amount"><span class="th">จำนวนเงิน</span></div>
    </div>

    <div class="product-body">
        {% call item_table(["col-no", "col-description", "col-quantity", "col-unit-price", "col-amount"], classes="item-lines") %}
        <tbody>
            {% for item in page_items %}
            {% set row = item %}
            <tr class="item-row">
                <td class="cell-no">{{ row.idx }}</td>
                <td class="cell-description">
                    <div class="item-main-line">{{ row.item_code }}{% if row.description or row.item_name %}/ {{
                        (row.description or row.item_name) | striptags }}{% endif %}</div>
                    {% if print_context.show_batch_serial %}
                    {% for trace in item.traceability_lines %}
                    <div class="traceability-line"><span class="traceability-label">{{ trace.label }}:</span> {{
                        trace.value }}</div>
                    {% endfor %}
                    {% endif %}
                </td>
                <td class="cell-quantity">
                    <div class="item-main-line">{{ format_money(row.qty) }} {{ row.uom or row.stock_uom or "" }}</div>
                </td>
                <td class="cell-money">
                    <div class="item-main-line">{{ format_money(row.rate) }}</div>
                </td>
                <td class="cell-money">
                    <div class="item-main-line">{{ format_money(row.amount) }}</div>
                </td>
            </tr>
            {% endfor %}
        </tbody>
        {% endcall %}
    </div>

        <div class="summary-area">
            <div class="summary-top">
                <div class="summary-term">
                    <div class="terms-text">
                        <div class="terms-heading">หมายเหตุ / เงื่อนไข</div>
                        <div class="deposit-heading">เงื่อนไขการชำระเงินมัดจำ</div>
                        {{ (doc.terms or "") | safe }}
                        <div>เอกสารนี้เป็นใบแจ้งหนี้สำหรับเรียกเก็บเงินมัดจำ และไม่ใช่หลักฐานการรับชำระเงินจนกว่าจะมีการรับเงินจริง</div>
                    </div>
                </div>

                <div class="summary-side">
                    <table class="summary-table">
                        <tbody>
                            {{ summary_row("รวมเป็นเงิน", gross_amount) }}
                            {{ summary_row("หักส่วนลด", discount_amount) }}
                            {{ summary_row("มูลค่าเงินมัดจำก่อนภาษี", deposit_net) }}
                            {{ summary_row("ภาษีมูลค่าเพิ่ม " ~ format_money(vat_rate) ~ " %", vat_amount) }}
                        </tbody>
                    </table>
                </div>
            </div>

            <div class="summary-bottom">
                <div class="amount-in-words">
                    ({{ number_to_thai_currency(deposit_total, doc.currency) }}).
                </div>
                <div class="grand-total-label">จำนวนเงินมัดจำรวมทั้งสิ้น</div>
                <div class="grand-total-value">{{ format_money(deposit_total) }}</div>
            </div>
        </div>
    </section>

<footer class="approval-box signature-only-footer compact-signatures">
    <div class="signature-pane">
        {{ signature_row(authorized_action, "ผู้รับมอบอำนาจ") }}
    </div>
    <div class="signature-pane">
        <div class="approval-head">
            <div class="brand-top">
                <span class="on-behalf">ในนาม</span>
                <span class="print-meta">{{ current_print_page }}/{{ total_print_pages }}</span>
            </div>
            <div class="signature-company">บริษัท คอนเนคไดแอกโนสติกส์ จำกัด</div>
        </div>
        {{ signature_row(checked_action, "ผู้ตรวจสอบ") }}
    </div>
</footer>

</div>
{% endfor %}
{% endfor %}
